<?php
ob_start();session_id('imageReferenceCheck'.bin2hex(random_bytes(12)));session_start();$_SESSION['user']='superadmin';$_SESSION['expire']=time()+180;$cookie='PHPSESSID='.session_id();session_write_close();function referenceHttp($cookie,$body=null,$csrf=''){$h=curl_init('http://localhost/api/index.php/ali/'.($body===null?'config':'producto'));curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>110,CURLOPT_COOKIE=>$cookie,CURLOPT_HTTPHEADER=>['Content-Type: application/json','X-Ali-CSRF: '.$csrf]]);if($body!==null)curl_setopt_array($h,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($body)]);$raw=curl_exec($h);$status=curl_getinfo($h,CURLINFO_HTTP_CODE);curl_close($h);return [$status,json_decode($raw,true)];}try{[$status,$config]=referenceHttp($cookie);if($status!==200)throw new RuntimeException('Authentication failed');[$status,$gallery]=referenceHttp($cookie,['mode'=>'image_gallery','id'=>4679],$config['csrf']);if($status!==200||count($gallery['imagenes']??[])!==3)throw new RuntimeException('Gallery read failed');[$status,$data]=referenceHttp($cookie,['mode'=>'image_search','id'=>4679,'exact_model'=>'15-FD2378LA'],$config['csrf']);if($status!==200)throw new RuntimeException('Reference search failed');echo 'Installed search returned '.count($data['candidates']??[]).' reference images; gallery has 3 slots. No product images changed.'.PHP_EOL;}finally{session_start();$_SESSION=[];session_destroy();ob_end_flush();}
